                    + ',"b":' + json.dumps(key_b, ensure_ascii=False)
                    + ',"diff":' + _format6(diff)
                    + ',"p":' + _format6(p_value)
                    + ',"q":' + _format6(q_value)
                    + ',"reject":' + ("true" if reject else "false")
                    + '}'
                )

        return (
            '{"ranks":[' + ",".join(rank_items) + ']'
            + ',"pairs":[' + ",".join(pair_items) + ']}'
